window.TL = {"duration": 449.92, "scenes": [{"id": "s1", "label": "Opening | Key Conclusion", "start": 0, "end": 31.99}, {"id": "s2", "label": "01 | Market Shifts and the Limitations of Traditional Competition", "start": 31.99, "end": 88.83}, {"id": "s3", "label": "02 | Customer Needs and Pain Points", "start": 88.83, "end": 160.65}, {"id": "s4", "label": "03 | Competitor Perceptions and the Learning Design Gap", "start": 160.65, "end": 236.93}, {"id": "s5", "label": "04 | Repositioning: From workbooks to Learning Design", "start": 236.93, "end": 281.42}, {"id": "s6", "label": "05 | Proposed Positioning Statement and Brand Messages", "start": 281.42, "end": 339.86}, {"id": "s7", "label": "06 | Proposed Strategic Actions", "start": 339.86, "end": 420.3}, {"id": "s8", "label": "Closing", "start": 420.3, "end": 449.92}], "cont": ["s1", "s2", "s3", "s4", "s5", "s6", "s7", "s8"], "order": ["title", "l1_1", "l1_3", "l1_4", "l1_5", "l1_6", "l1_7", "h2", "l2_1", "l2_2", "l2_3", "l2_4", "l2_5", "l2_6", "l2_7", "l2_8", "l2_9", "l2_10", "l2_11", "l2_12", "l2_13", "h3", "l3_1", "l3_2", "l3_3", "l3_4", "l3_5", "l3_6", "l3_7", "l3_8", "l3_9", "l3_10", "l3_11", "l3_12", "l3_13", "l3_14", "l3_15", "l3_16", "h4", "l4_1", "l4_2", "l4_3", "l4_4", "l4_5", "l4_6", "l4_7", "l4_8", "l4_9", "l4_10", "l4_11", "l4_12", "h5", "l5_1", "l5_2", "l5_3", "l5_4", "l5_5", "l5_6", "l5_7", "h6", "l6_1", "l6_2", "l6_3", "l6_4", "l6_5", "l6_6", "l6_7", "l6_8", "h7", "l7_1", "l7_2", "l7_3", "l7_4", "l7_5", "l7_6", "l7_7", "l7_8", "l7_9", "l7_10", "l7_11", "l8_1", "l8_2", "l8_3", "l8_4", "l8_5", "l8_6"], "lines": {"title": {"scene": "s1", "text": "JEI Repositioning: Core Strategy", "start": 0.6, "end": 3.49, "words": [["jei", 0.54], ["repositioning", 1.5], ["core", 2.2], ["strategy", 2.72]]}, "l1_1": {"scene": "s1", "text": "Good morning, everyone.", "start": 4.54, "end": 5.71, "words": [["good", 4.47], ["morning", 4.73], ["everyone", 4.95]]}, "l1_3": {"scene": "s1", "text": "Today, I will share JEI's core repositioning strategy.", "start": 6.16, "end": 9.86, "words": [["today", 6.14], ["i", 6.68], ["will", 6.7], ["share", 6.88], ["jei's", 7.16], ["core", 8.06], ["repositioning", 8.42], ["strategy", 9.1]]}, "l1_4": {"scene": "s1", "text": "Let me start with our key conclusion.", "start": 10.56, "end": 12.52, "words": [["let", 10.48], ["me", 10.76], ["start", 10.9], ["with", 11.16], ["our", 11.32], ["key", 11.46], ["conclusion", 11.66]]}, "l1_5": {"scene": "s1", "text": "JEI must move beyond competing on workbooks, scale, and digital features.", "start": 12.97, "end": 17.72, "words": [["jei", 12.91], ["must", 13.73], ["move", 14.03], ["beyond", 14.27], ["competing", 14.63], ["on", 15.09], ["workbooks", 15.31], ["scale", 16.05], ["and", 16.51], ["digital", 16.57], ["features", 16.93]]}, "l1_6": {"scene": "s1", "text": "Our goal is to become the brand that designs learning to develop children's ability to learn independently.", "start": 18.17, "end": 23.62, "words": [["our", 18.16], ["goal", 18.38], ["is", 18.64], ["to", 18.82], ["become", 18.94], ["the", 19.16], ["brand", 19.34], ["that", 19.72], ["designs", 19.98], ["learning", 20.42], ["to", 20.74], ["develop", 20.92], ["children's", 21.24], ["ability", 21.8], ["to", 22.12], ["learn", 22.34], ["independently", 22.6]]}, "l1_7": {"scene": "s1", "text": "I will explain the market changes, customer needs, the competitive gap, our positioning, and the strategic actions we need to take.", "start": 24.32, "end": 31.44, "words": [["i", 24.32], ["will", 24.44], ["explain", 24.58], ["the", 24.9], ["market", 25.04], ["changes", 25.28], ["customer", 26.0], ["needs", 26.46], ["the", 27.1], ["competitive", 27.18], ["gap", 27.58], ["our", 28.28], ["positioning", 28.58], ["and", 29.38], ["the", 29.42], ["strategic", 29.56], ["actions", 29.92], ["we", 30.38], ["need", 30.64], ["to", 30.8], ["take", 30.92]]}, "h2": {"scene": "s2", "text": "01 | Market Shifts and the Limitations of Traditional Competition", "start": 32.89, "end": 36.92, "words": [["1", 32.83], ["market", 33.53], ["shifts", 33.75], ["and", 34.19], ["the", 34.49], ["limitations", 34.61], ["of", 35.09], ["traditional", 35.41], ["competition", 35.85]]}, "l2_1": {"scene": "s2", "text": "First, let’s look at the challenges we face.", "start": 37.72, "end": 40.22, "words": [["first", 37.62], ["let's", 38.36], ["look", 38.6], ["at", 38.72], ["the", 38.84], ["challenges", 38.94], ["we", 39.26], ["face", 39.56]]}, "l2_2": {"scene": "s2", "text": "Three changes are important.", "start": 40.67, "end": 42.26, "words": [["three", 40.63], ["changes", 40.93], ["are", 41.25], ["important", 41.49]]}, "l2_3": {"scene": "s2", "text": "First, the limitations of our business scale.", "start": 42.96, "end": 45.58, "words": [["first", 42.82], ["the", 43.62], ["limitations", 43.72], ["of", 44.16], ["our", 44.52], ["business", 44.64], ["scale", 44.9]]}, "l2_4": {"scene": "s2", "text": "JEI ranks fourth in the workbook market.", "start": 46.03, "end": 48.87, "words": [["jei", 45.94], ["ranks", 46.7], ["fourth", 46.98], ["in", 47.36], ["the", 47.64], ["workbook", 47.74], ["market", 48.22]]}, "l2_5": {"scene": "s2", "text": "We have about 300 locations, while some competitors have more than 700.", "start": 49.32, "end": 53.9, "words": [["we", 49.07], ["have", 49.47], ["about", 49.67], ["300", 49.89], ["locations", 50.29], ["while", 51.37], ["some", 51.59], ["competitors", 51.83], ["have", 52.29], ["more", 52.59], ["than", 52.79], ["700", 52.93]]}, "l2_6": {"scene": "s2", "text": "It is difficult to compete based on size.", "start": 54.35, "end": 56.79, "words": [["it", 54.29], ["is", 54.53], ["difficult", 54.67], ["to", 54.97], ["compete", 55.21], ["based", 55.61], ["on", 55.95], ["size", 56.15]]}, "l2_7": {"scene": "s2", "text": "Second, changes in the market.", "start": 57.49, "end": 59.37, "words": [["second", 57.39], ["changes", 58.19], ["in", 58.59], ["the", 58.77], ["market", 58.85]]}, "l2_8": {"scene": "s2", "text": "There are fewer children entering school, but spending per child is increasing.", "start": 59.82, "end": 64.1, "words": [["there", 59.78], ["are", 59.98], ["fewer", 60.12], ["children", 60.36], ["entering", 60.78], ["school", 61.12], ["but", 61.74], ["spending", 61.96], ["per", 62.32], ["child", 62.58], ["is", 62.94], ["increasing", 63.24]]}, "l2_9": {"scene": "s2", "text": "This means there are fewer customers, but parents are willing to spend more when they see clear value.", "start": 64.55, "end": 69.47, "words": [["this", 64.47], ["means", 64.79], ["there", 65.03], ["are", 65.21], ["fewer", 65.33], ["customers", 65.57], ["but", 66.41], ["parents", 66.47], ["are", 66.85], ["willing", 67.01], ["to", 67.23], ["spend", 67.39], ["more", 67.63], ["when", 67.93], ["they", 68.15], ["see", 68.29], ["clear", 68.51], ["value", 68.77]]}, "l2_10": {"scene": "s2", "text": "Third, similar features across competitors.", "start": 70.17, "end": 72.87, "words": [["third", 70.17], ["similar", 70.69], ["features", 71.13], ["across", 71.51], ["competitors", 71.89]]}, "l2_11": {"scene": "s2", "text": "AI-based assessment, personalized learning paths, and grading have now become standard features.", "start": 73.32, "end": 78.65, "words": [["ai-based", 73.26], ["assessment", 73.94], ["personalized", 74.82], ["learning", 75.28], ["paths", 75.68], ["and", 76.16], ["grading", 76.44], ["have", 76.8], ["now", 77.08], ["become", 77.22], ["standard", 77.52], ["features", 77.88]]}, "l2_12": {"scene": "s2", "text": "As these features become increasingly common, we need a different basis for competition.", "start": 79.1, "end": 84.0, "words": [["as", 79.03], ["these", 79.31], ["features", 79.53], ["become", 79.89], ["increasingly", 80.23], ["common", 80.79], ["we", 81.55], ["need", 81.85], ["a", 82.01], ["different", 82.13], ["basis", 82.41], ["for", 82.83], ["competition", 83.09]]}, "l2_13": {"scene": "s2", "text": "This is why Learning Design is central to our repositioning strategy.", "start": 84.45, "end": 88.28, "words": [["this", 84.39], ["is", 84.63], ["why", 84.77], ["learning", 84.93], ["design", 85.23], ["is", 85.63], ["central", 85.91], ["to", 86.33], ["our", 86.59], ["repositioning", 86.73], ["strategy", 87.47]]}, "h3": {"scene": "s3", "text": "02 | Customer Needs and Pain Points", "start": 89.73, "end": 92.21, "words": [["2", 89.66], ["customer", 90.24], ["needs", 90.68], ["and", 91.04], ["pain", 91.26], ["points", 91.5]]}, "l3_1": {"scene": "s3", "text": "So, what are parents really willing to pay for?", "start": 93.01, "end": 95.54, "words": []}, "l3_2": {"scene": "s3", "text": "We can understand parents’ needs in three layers.", "start": 95.99, "end": 98.65, "words": []}, "l3_3": {"scene": "s3", "text": "The first layer is functional needs: learning materials for different levels, connections to school curricula, and learning data.", "start": 99.35, "end": 106.1, "words": []}, "l3_4": {"scene": "s3", "text": "The second layer is emotional needs.", "start": 106.55, "end": 108.58, "words": []}, "l3_5": {"scene": "s3", "text": "Parents want to worry less about their children falling behind.", "start": 109.03, "end": 112.17, "words": []}, "l3_6": {"scene": "s3", "text": "They also want someone to take care of their children’s learning.", "start": 112.62, "end": 115.51, "words": []}, "l3_7": {"scene": "s3", "text": "The third and most important layer is children’s ability to learn on their own.", "start": 116.21, "end": 120.22, "words": []}, "l3_8": {"scene": "s3", "text": "Why do parents discontinue learning programs?", "start": 120.92, "end": 123.46, "words": []}, "l3_9": {"scene": "s3", "text": "Children may become bored with repetitive activities.", "start": 123.91, "end": 126.9, "words": []}, "l3_10": {"scene": "s3", "text": "Standardized learning pace does not always meet individual needs.", "start": 127.35, "end": 131.09, "words": [["standardized", 127.24], ["learning", 128.06], ["pace", 128.3], ["does", 128.66], ["not", 128.88], ["always", 129.16], ["meet", 129.5], ["individual", 129.78], ["needs", 130.18]]}, "l3_11": {"scene": "s3", "text": "Parents struggle to see clear learning outcomes or understand what their children should learn next.", "start": 131.54, "end": 136.75, "words": [["parents", 131.49], ["struggle", 131.91], ["to", 132.27], ["see", 132.49], ["clear", 132.71], ["learning", 133.11], ["outcomes", 133.37], ["or", 133.85], ["understand", 134.27], ["what", 134.75], ["their", 135.05], ["children", 135.25], ["should", 135.57], ["learn", 135.83], ["next", 136.07]]}, "l3_12": {"scene": "s3", "text": "And much of the responsibility for managing their children's learning still falls on the parents.", "start": 137.2, "end": 141.94, "words": [["and", 137.2], ["much", 137.38], ["of", 137.62], ["the", 137.74], ["responsibility", 137.84], ["for", 138.4], ["managing", 138.78], ["their", 139.18], ["children's", 139.46], ["learning", 139.9], ["still", 140.2], ["falls", 140.66], ["on", 141.04], ["the", 141.18], ["parents", 141.26]]}, "l3_13": {"scene": "s3", "text": "These reasons point to one problem.", "start": 142.64, "end": 144.6, "words": [["these", 142.54], ["reasons", 142.92], ["point", 143.26], ["to", 143.56], ["one", 143.7], ["problem", 143.92]]}, "l3_14": {"scene": "s3", "text": "The problem is not simply a lack of learning materials.", "start": 145.05, "end": 148.01, "words": [["the", 145.05], ["problem", 145.17], ["is", 145.45], ["not", 145.65], ["simply", 145.83], ["a", 146.21], ["lack", 146.39], ["of", 146.65], ["learning", 146.83], ["materials", 147.07]]}, "l3_15": {"scene": "s3", "text": "Parents need a clearer understanding of what their children should learn next, why it matters, and how their learning will progress.", "start": 148.46, "end": 154.54, "words": [["parents", 148.33], ["need", 148.85], ["a", 149.01], ["clearer", 149.15], ["understanding", 149.47], ["of", 150.09], ["what", 150.35], ["their", 150.49], ["children", 150.65], ["should", 150.95], ["learn", 151.17], ["next", 151.37], ["why", 151.95], ["it", 152.27], ["matters", 152.41], ["and", 152.93], ["how", 153.07], ["their", 153.21], ["learning", 153.37], ["will", 153.63], ["progress", 153.81]]}, "l3_16": {"scene": "s3", "text": "This is why we must shift our focus from workbooks to how children’s ability to learn improves.", "start": 154.99, "end": 160.1, "words": [["this", 154.87], ["is", 155.25], ["why", 155.41], ["we", 155.61], ["must", 155.79], ["shift", 155.97], ["our", 156.25], ["focus", 156.41], ["from", 156.75], ["workbooks", 157.03], ["to", 157.67], ["how", 157.95], ["children's", 158.11], ["ability", 158.59], ["to", 158.89], ["learn", 159.11], ["improves", 159.31]]}, "h4": {"scene": "s4", "text": "03 | Competitor Perceptions and the Learning Design Gap", "start": 161.55, "end": 164.78, "words": [["3", 161.41], ["competitor", 162.11], ["perceptions", 162.75], ["and", 163.19], ["the", 163.59], ["learning", 163.69], ["design", 163.91], ["gap", 164.33]]}, "l4_1": {"scene": "s4", "text": "Now, let’s look at whether our competitors are meeting this need.", "start": 165.58, "end": 169.15, "words": []}, "l4_2": {"scene": "s4", "text": "These evaluations are based on customer perceptions.", "start": 169.6, "end": 172.61, "words": []}, "l4_3": {"scene": "s4", "text": "Each of our three major competitors is associated with a different strength.", "start": 173.31, "end": 177.47, "words": []}, "l4_4": {"scene": "s4", "text": "Daekyo emphasizes level-based learning, Kumon is known for repetition and building study habits, and Woongjin focuses on online and AI-powered learning platforms.", "start": 177.92, "end": 188.13, "words": []}, "l4_5": {"scene": "s4", "text": "Daekyo does not have a clear long-term learning plan.", "start": 188.83, "end": 192.28, "words": []}, "l4_6": {"scene": "s4", "text": "Kumon can become boring, causing children to lose interest.", "start": 192.73, "end": 196.19, "words": []}, "l4_7": {"scene": "s4", "text": "Woongjin's platform may feel complex, while screen-based learning can raise concerns about insufficient handwriting practice.", "start": 196.64, "end": 203.17, "words": []}, "l4_8": {"scene": "s4", "text": "Above all, no company clearly answers the question parents really ask: “Where should my child’s learning be in three years?”", "start": 203.87, "end": 210.63, "words": []}, "l4_9": {"scene": "s4", "text": "This is where “Design” comes in.", "start": 211.08, "end": 212.68, "words": []}, "l4_10": {"scene": "s4", "text": "It means setting a direction after diagnosis and helping children stay motivated along the way.", "start": 213.13, "end": 218.3, "words": []}, "l4_11": {"scene": "s4", "text": "According to Al Ries’s positioning principles, it is very difficult for a company ranked fourth to beat the leader in the same category.", "start": 219.0, "end": 225.82, "words": []}, "l4_12": {"scene": "s4", "text": "Rather than trying to move up the existing competitive ladder, JEI aims to establish a new ladder centered on Learning Design—one where we can build a distinctive leadership position.", "start": 226.27, "end": 236.38, "words": []}, "h5": {"scene": "s5", "text": "04 | Repositioning: From workbooks to Learning Design", "start": 237.83, "end": 241.15, "words": [["4", 237.69], ["repositioning", 238.85], ["from", 239.29], ["workbooks", 239.49], ["to", 240.03], ["learning", 240.23], ["design", 240.45]]}, "l5_1": {"scene": "s5", "text": "We will move from selling workbooks to providing Learning Design.", "start": 241.95, "end": 245.42, "words": []}, "l5_2": {"scene": "s5", "text": "We aim to provide personalized learning roadmaps that help each child understand what to learn next and how to progress.", "start": 245.87, "end": 252.3, "words": []}, "l5_3": {"scene": "s5", "text": "We will build on our existing strengths: the JEI Self-Learning Method, diagnostic assessment, and structured learning materials.", "start": 253.0, "end": 260.14, "words": []}, "l5_4": {"scene": "s5", "text": "But we will define self-learning as an ability, not just the act of studying.", "start": 260.59, "end": 264.73, "words": []}, "l5_5": {"scene": "s5", "text": "This builds on the nearly 50-year legacy of the JEI Self-Learning Method.", "start": 265.18, "end": 269.82, "words": []}, "l5_6": {"scene": "s5", "text": "Our focus is not simply to have more locations or members than competitors.", "start": 270.52, "end": 274.88, "words": []}, "l5_7": {"scene": "s5", "text": "We want to create clear learning paths for individual students and become a leader in the Learning Design category.", "start": 275.33, "end": 280.87, "words": []}, "h6": {"scene": "s6", "text": "05 | Proposed Positioning Statement and Brand Messages", "start": 282.32, "end": 286.14, "words": [["5", 282.07], ["proposed", 282.97], ["positioning", 283.67], ["statement", 284.09], ["and", 284.49], ["brand", 285.01], ["messages", 285.31]]}, "l6_1": {"scene": "s6", "text": "Our proposed positioning statement is: \"JEI designs learning to develop children's ability to learn independently.\"", "start": 286.94, "end": 293.33, "words": []}, "l6_2": {"scene": "s6", "text": "This statement reflects our shift from simply providing workbooks to developing children's Self-Learning Ability through Learning Design.", "start": 294.03, "end": 300.91, "words": []}, "l6_3": {"scene": "s6", "text": "Our brand messaging is built around two key concepts: \"Design\" and \"Self-Learning Ability.\"", "start": 301.61, "end": 306.81, "words": []}, "l6_4": {"scene": "s6", "text": "We have proposed several slogan options, including \"Learning starts with design,\" \"Studying starts with design,\" and \"Beyond Workbooks. Toward Learning Design.\"", "start": 307.51, "end": 316.15, "words": []}, "l6_5": {"scene": "s6", "text": "Our proposed campaign message is: \"It's not a lack of ability. It's a lack of learning design.\"", "start": 316.85, "end": 322.18, "words": []}, "l6_6": {"scene": "s6", "text": "And our customer value message is: \"The ability to learn independently begins with Learning Design.\"", "start": 322.88, "end": 328.32, "words": []}, "l6_7": {"scene": "s6", "text": "These are proposed expressions, not finalized brand slogans.", "start": 329.02, "end": 332.71, "words": []}, "l6_8": {"scene": "s6", "text": "Whatever we ultimately choose, our messages must reinforce a clear and consistent position in customers' minds.", "start": 333.16, "end": 339.31, "words": []}, "h7": {"scene": "s7", "text": "06 | Proposed Strategic Actions", "start": 340.76, "end": 343.65, "words": [["6", 340.68], ["proposed", 341.5], ["strategic", 342.14], ["actions", 342.64]]}, "l7_1": {"scene": "s7", "text": "Finally, let me outline five strategic priorities for execution.", "start": 344.45, "end": 348.47, "words": []}, "l7_2": {"scene": "s7", "text": "First, we will focus on our strongest core subjects rather than promoting all 17 subjects equally.", "start": 349.17, "end": 354.87, "words": []}, "l7_3": {"scene": "s7", "text": "This will allow us to build a clear and differentiated Learning Design approach.", "start": 355.32, "end": 359.5, "words": []}, "l7_4": {"scene": "s7", "text": "Second, we will strengthen the connection between assessment, Learning Design, and coaching.", "start": 360.2, "end": 365.2, "words": []}, "l7_5": {"scene": "s7", "text": "Each child's learning needs will be assessed, the next learning steps will be designed, and instructors will provide personalized guidance along the way.", "start": 365.65, "end": 374.17, "words": []}, "l7_6": {"scene": "s7", "text": "Third, we will continue to emphasize the role of our instructors.", "start": 374.87, "end": 378.6, "words": []}, "l7_7": {"scene": "s7", "text": "While AI-powered learning solutions are important, personal guidance and ongoing learning support remain key reasons why parents choose JEI.", "start": 379.05, "end": 386.82, "words": []}, "l7_8": {"scene": "s7", "text": "Fourth, we will communicate a consistent brand message across our products, learning centers, local offices, and advertising.", "start": 387.52, "end": 394.2, "words": []}, "l7_9": {"scene": "s7", "text": "\"Design\" and \"Self-Learning Ability\" should remain central to how we present our brand.", "start": 394.65, "end": 399.21, "words": []}, "l7_10": {"scene": "s7", "text": "Fifth, we will focus on increasing value per customer and recognize the importance of multi-subject learning, while avoiding competition based solely on the number of subjects or overall business scale.", "start": 399.91, "end": 411.35, "words": []}, "l7_11": {"scene": "s7", "text": "Together, these priorities will help JEI strengthen its position in Learning Design and deliver greater value to children and their families.", "start": 412.05, "end": 419.75, "words": []}, "l8_1": {"scene": "s8", "text": "To summarize, JEI aims to move beyond workbooks and establish a leadership position in Learning Design by designing learning to develop children's ability to learn independently.", "start": 421.2, "end": 431.32, "words": []}, "l8_2": {"scene": "s8", "text": "To achieve this, we must change first.", "start": 432.02, "end": 434.36, "words": []}, "l8_3": {"scene": "s8", "text": "When we develop products, meet customers, and discuss ideas in meetings, we must all use the same language.", "start": 434.81, "end": 440.43, "words": []}, "l8_4": {"scene": "s8", "text": "Starting today, our shared message is “Designing the Ability to Learn.”", "start": 440.88, "end": 444.73, "words": []}, "l8_5": {"scene": "s8", "text": "Thank you.", "start": 445.43, "end": 446.09, "words": []}, "l8_6": {"scene": "s8", "text": "Please feel free to ask any questions.", "start": 446.54, "end": 448.72, "words": []}}};
